const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
function toast(message){$('#toastText').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function switchView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===id));const titles={dashboard:'早安，林店長 👋',kitchen:'飲料製作儀表板',survey:'市場洞察',inventory:'庫存管理',season:'時令行動',roadmap:'AI 導入路線',localai:'AI 營運中心 (測試中)'};$('#viewTitle').textContent=titles[id];window.scrollTo({top:0,behavior:'smooth'})}
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.go)));
$('#branchSelect').addEventListener('change',e=>{state.branch=e.target.value;const d=branchData[state.branch];Object.entries(d).forEach(([k,v])=>{const el=document.querySelector(`[data-kpi="${k}"]`);if(el)el.innerHTML=k==='alerts'?`${v} <span>項</span>`:v});toast(`已切換至${e.target.options[e.target.selectedIndex].text}`)});
const channelContent={online:{icon:'◎',title:'網路點單',description:'顧客使用手機或電腦下單；送出後取得即時取餐進度連結。'},tablet:{icon:'▣',title:'現場平板點單',description:'顧客在門市平板完成點單；送出後顯示取餐號碼、排隊杯數及等待時間。'},counter:{icon:'杯',title:'櫃台輔助點單',description:'店員代為輸入需求；送出後可口頭告知取餐號碼及預估時間。'}};
function selectChannel(channel){state.channel=channel;$$('.mode-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.channel===channel));const content=channelContent[channel];$('#channelIcon').textContent=content.icon;$('#channelTitle').textContent=content.title;$('#channelDescription').textContent=content.description}
$$('.mode-tabs button').forEach(b=>b.addEventListener('click',()=>{selectChannel(b.dataset.channel);toast(`已切換為${b.textContent}`)}));
$$('.chip-group').forEach(group=>group.addEventListener('click',e=>{if(!e.target.matches('.chip'))return;group.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));e.target.classList.add('active');state[group.dataset.group]=e.target.dataset.value}));
$$('.event-option').forEach(b=>b.addEventListener('click',()=>{$$('.event-option').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.event=b.dataset.event}));
const sweetNames=['無糖','微糖','半糖','少糖','正常甜'];$('#sweetRange')?.addEventListener('input',e=>$('#sweetLabel').textContent=sweetNames[e.target.value]);
function renderDrinks(){const list=drinkSets[state.event].slice(0,3);$('#drinkList').innerHTML=list.map((d,i)=>`<article class="drink-card"><div class="drink-visual" style="background:${d.color}"><span>${d.emoji}</span></div><span class="match">${d.match-i}% MATCH</span><h4>${d.name}</h4><p>${d.desc}</p><div class="drink-meta"><strong>$${d.price}</strong><button class="add-btn" data-index="${i}" aria-label="加入${d.name}">＋</button></div></article>`).join('');$$('.add-btn').forEach(b=>b.addEventListener('click',()=>addCart(list[Number(b.dataset.index)])))}
function renderFullMenu(filter='all'){const items=menuItems.filter(d=>filter==='all'||menuCategories[d.name].includes(filter));$('#menuCatalog').innerHTML=items.map(d=>`<article class="menu-item"><span style="background:${d.color}">${d.emoji}</span><div><strong>${d.name}</strong><small>${d.desc}</small></div><b>$${d.price}</b><button data-menu-name="${d.name}">加入點單</button></article>`).join('');$$('[data-menu-name]').forEach(b=>b.addEventListener('click',()=>addCart(menuItems.find(d=>d.name===b.dataset.menuName))))}
$$('.menu-filter-tabs button').forEach(b=>b.addEventListener('click',()=>{$$('.menu-filter-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderFullMenu(b.dataset.menuFilter)}));
function selectSeason(key){const d=seasonScenarios[key];if(!d)return;$$('.season-scenario-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.seasonScenario===key));$('#seasonPeriod').textContent=d.period;$('#seasonTitle').textContent=d.title;$('#seasonUrgency').textContent=d.urgency;$('#seasonReason').textContent=d.reason;$('#seasonSignal').textContent=d.signal;$('#seasonStores').textContent=d.stores;$('#seasonOpportunity').textContent=d.opportunity;$('#seasonActions').innerHTML=d.actions.map(([emoji,name,detail,label,cls])=>`<article class="season-action"><span>${emoji}</span><div><strong>${name}</strong><small>${detail}</small></div><b class="${cls}">${label}</b></article>`).join('')}
$$('.season-scenario-tabs button').forEach(b=>b.addEventListener('click',()=>selectSeason(b.dataset.seasonScenario)));$('#approveSeasonPlan').addEventListener('click',()=>toast('時令行動已建立草稿，等待店長核准'));$('#addSeasonReminder').addEventListener('click',()=>toast('已建立新的自訂時段提醒'));
function addCart(drink){state.cart.push(drink);renderCart();toast(`已加入「${drink.name}」`)}
function renderCart(){$('#cartCount').textContent=state.cart.length;$('#cartTotal').textContent=`$${state.cart.reduce((s,d)=>s+d.price,0)}`;$('#cartItems').innerHTML=state.cart.length?state.cart.map((d,i)=>`<div class="cart-item"><span>${d.emoji}</span><div><strong>${d.name}</strong><small>${$('#sweetLabel').textContent}・正常冰</small></div><button data-remove="${i}" aria-label="移除">×</button></div>`).join(''):'<p class="empty-state">尚未加入飲品</p>';$$('[data-remove]').forEach(b=>b.addEventListener('click',()=>{state.cart.splice(Number(b.dataset.remove),1);renderCart()}))}
$('#generateRecommendation')?.addEventListener('click',()=>{renderDrinks();const dairy=$('#dairyFree').checked?'並避開乳製品，':'';$('#recommendReason').textContent=`今天氣溫下降 4°C，${dairy}你偏好${state.flavor}與${state.scene}感；推薦已依即時庫存重新排序。`;toast('AI 已重新計算推薦')});
function toggleCart(open){$('#cartDrawer')?.classList.toggle('open',open);$('#drawerBackdrop')?.classList.toggle('open',open)}$('#openCart')?.addEventListener('click',()=>toggleCart(true));$('#closeCart')?.addEventListener('click',()=>toggleCart(false));$('#drawerBackdrop')?.addEventListener('click',()=>toggleCart(false));
function placeOrder(){if(!state.cart.length)return toast('請先加入飲品');const number=`A${state.nextOrder++}`;const created=new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit',hour12:false});const sweet=$('#sweetLabel').textContent;const cups=state.cart.map((drink,index)=>({number:state.cart.length>1?`${number}-${index+1}`:number,created,status:'new',channel:state.channel,drink:{...drink},sweet,ice:'正常冰',rush:false}));state.orders.push(...cups);state.lastCustomerOrder={number,cups:cups.length,channel:state.channel};state.cart=[];renderCart();renderKitchen();toggleCart(false);toast(`${number} 已同步到製作區平板`);setTimeout(()=>showCustomerStatus(state.lastCustomerOrder),280)}
$('#checkoutBtn')?.addEventListener('click',placeOrder);
function showCustomerStatus(order){const copy={online:{channel:'網路下單',icon:'◎',title:'訂單狀態連結已建立',description:'可從瀏覽器、簡訊或會員頁持續查看進度。'},tablet:{channel:'現場平板下單',icon:'▣',title:'平板已顯示取餐 QR',description:'掃描後可在手機持續查看進度，不必留在櫃台等候。'},counter:{channel:'櫃台下單',icon:'杯',title:'取餐號碼已建立',description:'店員可告知目前排隊杯數及預估等待時間。'}}[order.channel];$('#statusChannel').textContent=copy.channel;$('#customerOrderNumber').textContent=order.number;$('#customerOrderCups').textContent=`共 ${order.cups} 杯`;$('#deliveryIcon').textContent=copy.icon;$('#deliveryTitle').textContent=copy.title;$('#deliveryDescription').textContent=copy.description;refreshCustomerProgress();$('#statusBackdrop').classList.add('open');$('#statusBackdrop').setAttribute('aria-hidden','false')}
function refreshCustomerProgress(){if(!state.lastCustomerOrder||!$('#customerStatusTitle'))return;const base=state.lastCustomerOrder.number;const ownRemaining=state.orders.filter(o=>o.number===base||o.number.startsWith(`${base}-`)).length;if(ownRemaining===0){$('#customerStatusTitle').textContent='飲料製作完成，可以取餐。';$('#customerQueueCount').textContent='0 杯';$('#customerWaitTime').textContent='可取餐';$$('.customer-progress>div').forEach(x=>x.classList.add('done'));return}const queueCount=state.orders.length;$('#customerStatusTitle').textContent='已下單，正在排入製作。';$('#customerQueueCount').textContent=`${queueCount} 杯`;$('#customerWaitTime').textContent=`約 ${Math.max(3,Math.ceil(queueCount*1.7))} 分鐘`}
function closeCustomerStatus(){$('#statusBackdrop').classList.remove('open');$('#statusBackdrop').setAttribute('aria-hidden','true')}
$('#closeStatus')?.addEventListener('click',closeCustomerStatus);$('#continueOrdering')?.addEventListener('click',()=>{closeCustomerStatus();switchView('dashboard')});$('#viewKitchenFromStatus')?.addEventListener('click',()=>{closeCustomerStatus();switchView('kitchen')});$('#statusBackdrop')?.addEventListener('click',e=>{if(e.target===$('#statusBackdrop'))closeCustomerStatus()});
function recipeFor(name){return recipeDB[name]||{base:'茶湯 300ml',flavor:'風味原料 30ml',water:'冰塊 160g',finish:'搖勻 10 次',steps:['依標準杯量取原料','加入茶湯與冰塊','確認標籤後封膜']}}
function renderKitchen(){
  const queue=$('#recipeQueue');if(!queue)return;
  queue.innerHTML=state.orders.length?state.orders.map((o,index)=>{const r=recipeFor(o.drink.name);return `<article class="recipe-ticket ${o.rush?'rush':''}"><div class="ticket-head"><span class="order-number">${o.number}</span><span><strong>${o.status==='making'?'製作中':'新訂單'}</strong><small>${o.created}・櫃台點單</small></span><b class="ticket-wait">${o.rush?'優先製作':o.status==='making'?'計時中':'剛送達'}</b></div><div class="drink-recipe"><div class="recipe-title"><span><em>${o.drink.emoji}</em><strong>${o.drink.name}</strong></span><small>700 ml</small></div><div class="custom-tags"><span>${o.sweet}</span><span>${o.ice}</span><span>標準配方</span></div><div class="recipe-grid"><div class="recipe-step"><small>基底</small><strong>${r.base}</strong></div><div class="recipe-step"><small>風味</small><strong>${r.flavor}</strong></div><div class="recipe-step"><small>水／冰</small><strong>${r.water}</strong></div><div class="recipe-step"><small>完成</small><strong>${r.finish}</strong></div></div><div class="step-list">${r.steps.map((s,i)=>`<div><i>${i+1}</i><span>${s}</span></div>`).join('')}</div></div><div class="ticket-actions"><button class="start-btn ${o.status==='making'?'making':''}" data-order-index="${index}">${o.status==='making'?'✓ 完成出杯':'開始製作'}</button><button class="recipe-info-btn" data-recipe-name="${o.drink.name}" aria-label="查看配方資訊">i</button></div></article>`}).join(''):'<div class="empty-kitchen"><span>✓</span><strong>目前沒有待製作飲料</strong><small>新訂單會自動顯示在這裡</small></div>';
  $('#completedOrders').innerHTML=state.completed.slice(0,6).map(o=>`<div class="completed-ticket"><span>✓</span><div><strong>${o.number}・${o.name}</strong><small>${o.finished} 完成・已扣庫存</small></div><b>可取餐</b></div>`).join('');
  $('#waitingCount').textContent=`${state.orders.length} 杯`;$('#completedCount').textContent=`${state.completed.length} 杯`;$('#kitchenBadge').textContent=state.orders.length;$('#deductCount').textContent=`今日 ${state.deductCount} 次`;
  $$('.start-btn').forEach(b=>b.addEventListener('click',()=>advanceOrder(Number(b.dataset.orderIndex))));$$('.recipe-info-btn').forEach(b=>b.addEventListener('click',()=>toast(`${b.dataset.recipeName}：配方版本 v3.2`)));
}
function advanceOrder(index){const order=state.orders[index];if(!order)return;if(order.status==='new'){order.status='making';renderKitchen();refreshCustomerProgress();toast(`${order.number} 開始製作，計時已啟動`);return}state.orders.splice(index,1);state.completed.unshift({number:order.number,name:order.drink.name,finished:new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit',hour12:false})});state.deductCount++;renderKitchen();refreshCustomerProgress();toast(`${order.number} 完成，配方庫存已同步扣除`)}
function renderInventory(filter='all'){$('#inventoryRows').innerHTML=inventory.filter(x=>filter==='all'||x.status===filter).map(x=>`<tr><td><strong>${x.item}</strong><small>原料批次已同步</small></td><td>${x.store}</td><td><strong>${x.stock}</strong><div class="stock-bar"><i style="width:${x.level}%;background:${x.status==='critical'?'#d75e53':x.status==='warning'?'#dcaa55':'#4d9878'}"></i></div></td><td>${x.safe}</td><td><span class="row-status ${x.status}">${x.eta}</span></td><td>${x.advice}</td><td><button class="row-action" data-row="${x.item}">${x.status==='good'?'查看':'處理'}</button></td></tr>`).join('');$$('.row-action').forEach(b=>b.addEventListener('click',()=>b.textContent==='處理'?$('#actionDialog').showModal():toast(`${b.dataset.row}庫存狀態正常`)))}
function selectInsightBranch(key){const d=branchInsights[key];if(!d)return;$$('.branch-profile-card').forEach(x=>x.classList.toggle('active',x.dataset.insightBranch===key));$('#insightOrderCount').textContent=`近 30 天・${d.orders} 杯`;$('#insightBranchName').textContent=`${d.name}點單偏好`;$('#primaryPreference').textContent=`${d.primary}%`;$('#primaryLabel').textContent=d.label;$('#orderDonut').style.background=`conic-gradient(var(--green) 0 ${d.primary}%,#e5b47c ${d.primary}% 67%,#7ea6a0 67% 87%,#ddd7e8 87%)`;$('#orderPreferenceBars').innerHTML=d.bars.map(([label,value])=>`<div><span><b>${label}</b><em>${value}%</em></span><i><b style="width:${value}%"></b></i></div>`).join('');$('#orderInsightTitle').textContent=d.insight;$('#orderInsightDetail').textContent=d.detail;$('#testProductName').textContent=d.product;$('#testProductEmoji').textContent=d.emoji;$('#testProductReason').textContent=d.reason;$('#testQuantity').textContent=d.quantity;$('#testThreshold').textContent=d.threshold;$('#signalTime').textContent=d.time;$('#signalTimeText').textContent=d.timeText;$('#signalSweet').textContent=d.sweet;$('#signalSweetText').textContent=d.sweetText;$('#signalPrice').textContent=d.price;$('#signalPriceText').textContent=d.priceText;$('#priceAdviceBranch').textContent=d.priceTitle;$('#priceDecisionIcon').textContent=d.priceIcon;$('#priceDecisionProduct').textContent=d.priceProduct;$('#priceDecisionText').textContent=d.priceText2;$('#priceDecisionReason').textContent=d.priceReason;$('#priceTestScope').textContent=d.scope;$('#priceStopRule').textContent=d.stop;$('#priceMarginImpact').textContent=d.impact}
$$('.branch-profile-card').forEach(b=>b.addEventListener('click',()=>selectInsightBranch(b.dataset.insightBranch)));$('#createProductTest').addEventListener('click',()=>toast('已建立新品小量測試草稿，等待店長核准'));$('#createPriceTest').addEventListener('click',()=>toast('已建立調價測試草稿，售價尚未變更'));
